def _patch_quiz_extra(path: pathlib.Path) -> int:
    if path.is_file():
        data = json.loads(path.read_text(encoding="utf-8"))
        items = data.get("questions") if isinstance(data, dict) else data
    else:
        data = []
        items = data
    if not isinstance(items, list):
        raise ValueError(f"Unexpected quiz_extra.json format in {path}")
    existing = {str(x.get("q", "")).strip() for x in items}
    added = 0
    for q in EXTRA_QUIZ_20:
        if q["q"].strip() not in existing:
            items.append(q)
            existing.add(q["q"].strip())
            added += 1
    if added or not path.is_file():
        if isinstance(data, dict):
            data["questions"] = items
            path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        else:
            path.write_text(json.dumps(items, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return added


def _patch_glossary_builder(path: pathlib.Path) -> bool:
    if not path.is_file():
        return False
    txt = path.read_text(encoding="utf-8")
    if '"NDSRI"' in txt and '"OPDP"' in txt:
        return False
    anchor = "def build_v61b_reference("
    if anchor not in txt:
        return False
    add_block = (
        "\n# v6.2t: Expand Acronym Glossary from 60 -> 80 terms across all v6.2 domains\n"
        "_V62T_EXTRA_GLOSSARY = " + json.dumps(EXTRA_GLOSSARY_20, indent=4, ensure_ascii=False) + "\n"
        "for _gt in _V62T_EXTRA_GLOSSARY:\n"
        "    if not any(x.get('term') == _gt['term'] for x in GLOSSARY_TERMS):\n"
        "        GLOSSARY_TERMS.append(_gt)\n\n"
    )
    path.write_text(txt.replace(anchor, add_block + anchor, 1), encoding="utf-8")
    return True


def apply_patch(root: pathlib.Path) -> dict:
    pipe_dir = root / "pipeline"
    return {
        "quiz_batch3_questions_added": _patch_quiz_extra(pipe_dir / "quiz_extra.json"),
        "glossary_expanded_to_80": _patch_glossary_builder(pipe_dir / "build_v61b_reference.py"),
    }


def selftest() -> None:
    with tempfile.TemporaryDirectory() as td:
        root = pathlib.Path(td)
        (root / "pipeline").mkdir()
        (root / "site" / "data").mkdir(parents=True)

        seed_q = [{"q": f"Existing Q{i}?", "choices": ["A", "B", "C", "D"], "answer": 0, "explain": "x", "source": "FDA", "url": "https://www.fda.gov/"} for i in range(30)]
        (root / "pipeline" / "quiz_extra.json").write_text(json.dumps(seed_q), encoding="utf-8")
        (root / "pipeline" / "build_v61b_reference.py").write_text(
            'import json, pathlib, sys\n'
            'GLOSSARY_TERMS = [{"term": f"T{i}", "full": f"Term {i}", "category": "Reg", "plain": "p", "technical": "t", "link": "#/ref", "source": "https://www.fda.gov/"} for i in range(60)]\n'
            'def build_v61b_reference(d):\n'
            '    (pathlib.Path(d) / "glossary.json").write_text(json.dumps({"count": len(GLOSSARY_TERMS), "terms": GLOSSARY_TERMS}), encoding="utf-8")\n'
            'if __name__ == "__main__": build_v61b_reference(sys.argv[1])\n',
            encoding="utf-8",
        )

        r1 = apply_patch(root)
        assert r1["quiz_batch3_questions_added"] == 20 and r1["glossary_expanded_to_80"], r1
        r2 = apply_patch(root)
        assert r2["quiz_batch3_questions_added"] == 0 and not r2["glossary_expanded_to_80"], r2

        qdoc = json.loads((root / "pipeline" / "quiz_extra.json").read_text(encoding="utf-8"))
        assert len(qdoc) == 50 and all(q["url"].startswith("https://") for q in qdoc)

        subprocess.run([sys.executable, str(root / "pipeline" / "build_v61b_reference.py"), str(root / "site" / "data")], check=True)
        gdoc = json.loads((root / "site" / "data" / "glossary.json").read_text(encoding="utf-8"))
        assert gdoc["count"] == 80 and all(t["source"].startswith("https://") for t in gdoc["terms"]), gdoc["count"]

        print("V62T_QUIZ100_GLOSSARY80_SELFTEST_PASSED", json.dumps({"extra_quiz_total": len(qdoc), "glossary_total": gdoc["count"], **r1}, indent=2))


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="Apply Pill by Pill v6.2t Quiz (80 -> 100) & Glossary (60 -> 80) Expansion patch.")
    ap.add_argument("--apply", type=pathlib.Path, help="Path to unpacked source directory")
    ap.add_argument("--selftest", action="store_true", help="Run built-in verification tests")
    args = ap.parse_args(argv)
    if args.selftest:
        selftest()
        return 0
    if args.apply:
        print(json.dumps(apply_patch(args.apply), indent=2))
        return 0
    ap.error("Provide --apply <dir> or --selftest")
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
